import { filterSuccessful, filterUnsuccessful } from "@allurereport/core-api";
import { bold } from "yoctocolors";
const numberStateValue = (value) => (Number.isFinite(value) ? Number(value) : 0);
const stringArrayStateValue = (value) => Array.isArray(value) ? value.filter((item) => typeof item === "string") : [];
const successRateStateValue = (value) => {
    if (typeof value !== "object" || value === null) {
        return { totalCount: 0, passedCount: 0 };
    }
    const state = value;
    return {
        totalCount: numberStateValue(state.totalCount),
        passedCount: numberStateValue(state.passedCount),
    };
};
const metricValues = (metrics, key) => metrics
    .map((metric) => (metric.key === key ? metric.value : undefined))
    .filter((value) => Number.isFinite(value));
const metricAverage = (metrics, key) => {
    const values = metricValues(metrics, key);
    if (values.length === 0) {
        return undefined;
    }
    return values.reduce((acc, value) => acc + value, 0) / values.length;
};
const previousMetricValue = (history, key) => {
    const previousHistory = [...history].sort((a, b) => (b.timestamp ?? 0) - (a.timestamp ?? 0));
    for (const historyPoint of previousHistory) {
        const value = historyPoint.metrics?.[key];
        if (Number.isFinite(value)) {
            return value;
        }
    }
    return undefined;
};
const metricActual = (metrics, key, value) => {
    const sample = metrics.find((metric) => metric.key === key);
    return {
        key,
        value,
        ...(sample?.title ? { title: sample.title } : {}),
        ...(sample?.unit ? { unit: sample.unit } : {}),
    };
};
const formatMetricValue = (value, unit) => {
    if (!Number.isFinite(value)) {
        return "n/a";
    }
    const finiteValue = value;
    const formatted = Number.isInteger(finiteValue) ? String(finiteValue) : String(Number(finiteValue.toFixed(3)));
    return unit ? `${formatted} ${unit}` : formatted;
};
const metricRuleTitle = (actual) => actual.title ?? actual.key;
const metricRuleUnit = (actual, expected) => actual.unit ?? expected.unit;
const missingMetricResult = (actual) => ({
    success: false,
    actual,
    testResults: [],
});
const metricRuleResult = (success, actual) => ({
    success,
    actual,
    testResults: [],
});
const metricDeltaWithinThreshold = (delta, threshold, better) => {
    if (better === "lower") {
        return delta <= threshold;
    }
    if (better === "higher") {
        return -delta <= threshold;
    }
    return Math.abs(delta) <= threshold;
};
export const maxFailuresRule = {
    rule: "maxFailures",
    message: ({ actual, expected }) => `The number of failed tests ${bold(String(actual))} exceeds the allowed threshold value ${bold(String(expected))}`,
    validate: async ({ trs, expected, state }) => {
        const previous = numberStateValue(state.getResult());
        const failedTrs = trs.filter(filterUnsuccessful);
        const testResults = failedTrs.map((tr) => tr.id);
        const actual = previous + failedTrs.length;
        state.setResult(actual, testResults);
        return {
            success: actual <= expected,
            actual,
            testResults,
        };
    },
};
export const minTestsCountRule = {
    rule: "minTestsCount",
    message: ({ actual, expected }) => `The total number of tests ${bold(String(actual))} is less than the expected threshold value ${bold(String(expected))}`,
    validate: async ({ trs, expected, state }) => {
        const actual = trs.length + numberStateValue(state.getResult());
        state.setResult(actual, []);
        return {
            success: actual >= expected,
            actual,
            testResults: [],
        };
    },
};
export const successRateRule = {
    rule: "successRate",
    message: ({ actual, expected }) => `Success rate ${bold(String(actual))} is less, than expected ${bold(String(expected))}`,
    validate: async ({ trs, expected, state }) => {
        const previous = successRateStateValue(state.getResult());
        const passedTrs = trs.filter(filterSuccessful);
        const notPassedTrs = trs.filter((tr) => !filterSuccessful(tr));
        const totalCount = previous.totalCount + trs.length;
        const passedCount = previous.passedCount + passedTrs.length;
        const testResults = notPassedTrs.map((tr) => tr.id);
        const rate = totalCount === 0 ? 0 : passedCount / totalCount;
        state.setResult({ totalCount, passedCount }, testResults);
        return {
            success: rate >= expected,
            actual: rate,
            testResults,
        };
    },
};
export const maxDurationRule = {
    rule: "maxDuration",
    message: ({ actual, expected }) => `Maximum duration of some tests exceed the defined limit; actual ${bold(String(actual))}, expected ${bold(String(expected))}`,
    validate: async ({ trs, expected, state }) => {
        const previous = numberStateValue(state.getResult());
        const actual = Math.max(previous, ...trs.map((tr) => tr.duration ?? 0));
        const tooLongTrs = trs.filter((tr) => (tr.duration ?? 0) > expected);
        const testResults = tooLongTrs.map((tr) => tr.id);
        state.setResult(actual, testResults);
        return {
            success: actual <= expected,
            actual,
            testResults,
        };
    },
};
export const allTestsContainEnvRule = {
    rule: "allTestsContainEnv",
    message: ({ actual, expected }) => `Not all tests contain the required "${bold(expected)}" environment, ${bold(String(actual))} tests have different or missing environment`,
    validate: async ({ trs, expected, state }) => {
        const previous = numberStateValue(state.getResult());
        const testsWithoutEnv = trs.filter((tr) => (tr.environment ?? "") !== expected);
        const testResults = testsWithoutEnv.map((tr) => tr.id);
        const actual = testsWithoutEnv.length + previous;
        state.setResult(actual, testResults);
        return {
            success: actual === 0,
            actual,
            testResults,
        };
    },
};
export const environmentsTestedRule = {
    rule: "environmentsTested",
    message: ({ actual, expected }) => `The following environments were not tested: "${actual.join('", "')}"; expected all of: "${expected.join('", "')}"`,
    validate: async ({ trs, expected, state }) => {
        const previouslyTested = new Set(stringArrayStateValue(state.getResult()));
        const batchTested = trs.map((tr) => tr.environment).filter((env) => env != null && env !== "");
        const testedEnvs = new Set([...previouslyTested, ...batchTested]);
        state.setResult([...testedEnvs], []);
        const missing = expected.filter((env) => !testedEnvs.has(env));
        return {
            success: missing.length === 0,
            actual: missing,
            testResults: [],
        };
    },
};
export const metricMaxRule = {
    rule: "metricMax",
    message: ({ actual, expected }) => `${bold(metricRuleTitle(actual))} ${bold(formatMetricValue(actual.value, metricRuleUnit(actual, expected)))} exceeds the allowed maximum ${bold(formatMetricValue(expected.value, metricRuleUnit(actual, expected)))}`,
    validate: async ({ metrics = [], expected }) => {
        const value = metricAverage(metrics, expected.key);
        const actual = metricActual(metrics, expected.key, value ?? Number.NaN);
        return value === undefined ? missingMetricResult(actual) : metricRuleResult(value <= expected.value, actual);
    },
};
export const metricMinRule = {
    rule: "metricMin",
    message: ({ actual, expected }) => `${bold(metricRuleTitle(actual))} ${bold(formatMetricValue(actual.value, metricRuleUnit(actual, expected)))} is below the required minimum ${bold(formatMetricValue(expected.value, metricRuleUnit(actual, expected)))}`,
    validate: async ({ metrics = [], expected }) => {
        const value = metricAverage(metrics, expected.key);
        const actual = metricActual(metrics, expected.key, value ?? Number.NaN);
        return value === undefined ? missingMetricResult(actual) : metricRuleResult(value >= expected.value, actual);
    },
};
export const metricMaxDeltaRule = {
    rule: "metricMaxDelta",
    message: ({ actual, expected }) => `${bold(metricRuleTitle(actual))} changed by ${bold(formatMetricValue(actual.value, metricRuleUnit(actual, expected)))}, which exceeds ${bold(formatMetricValue(expected.value, metricRuleUnit(actual, expected)))}`,
    validate: async ({ metrics = [], previousHistory = [], expected }) => {
        const current = metricAverage(metrics, expected.key);
        if (current === undefined) {
            return missingMetricResult(metricActual(metrics, expected.key, Number.NaN));
        }
        const previous = previousMetricValue(previousHistory, expected.key);
        if (previous === undefined) {
            return metricRuleResult(true, metricActual(metrics, expected.key, 0));
        }
        const value = current - previous;
        const actual = metricActual(metrics, expected.key, value);
        const better = metrics.find((metric) => metric.key === expected.key)?.better;
        return metricRuleResult(metricDeltaWithinThreshold(value, expected.value, better), actual);
    },
};
export const metricMaxDeltaPercentRule = {
    rule: "metricMaxDeltaPercent",
    message: ({ actual, expected }) => `${bold(metricRuleTitle(actual))} changed by ${bold(formatMetricValue(actual.value, "%"))}, which exceeds ${bold(formatMetricValue(expected.value, "%"))}`,
    validate: async ({ metrics = [], previousHistory = [], expected }) => {
        const current = metricAverage(metrics, expected.key);
        if (current === undefined) {
            return missingMetricResult(metricActual(metrics, expected.key, Number.NaN));
        }
        const previous = previousMetricValue(previousHistory, expected.key);
        if (previous === undefined) {
            return metricRuleResult(true, metricActual(metrics, expected.key, 0));
        }
        const value = previous !== 0 ? ((current - previous) / Math.abs(previous)) * 100 : Number.NaN;
        const actual = metricActual(metrics, expected.key, value);
        const better = metrics.find((metric) => metric.key === expected.key)?.better;
        return Number.isFinite(value)
            ? metricRuleResult(metricDeltaWithinThreshold(value, expected.value, better), actual)
            : missingMetricResult(actual);
    },
};
export const qualityGateDefaultRules = [
    maxFailuresRule,
    minTestsCountRule,
    successRateRule,
    maxDurationRule,
    allTestsContainEnvRule,
    environmentsTestedRule,
    metricMaxRule,
    metricMinRule,
    metricMaxDeltaRule,
    metricMaxDeltaPercentRule,
];
